import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        int n = sc.nextInt();

        double minDiff = 1e9;
        int bestNum = 0;
        int bestDen = 1;

        for (int b = 1; b <= n; b++) {
            double aCandidate1 = Math.ceil(b * x / y);
            double aCandidate2 = Math.floor(b * x / y);

            double diff1 = Math.abs(x / y - aCandidate1 / b);
            if (diff1 < minDiff) {
                minDiff = diff1;
                bestNum = (int) aCandidate1;
                bestDen = b;
            }

            double diff2 = Math.abs(x / y - aCandidate2 / b);
            if (diff2 < minDiff) {
                minDiff = diff2;
                bestNum = (int) aCandidate2;
                bestDen = b;
            }
        }

        System.out.println(bestNum + "/" + bestDen);
        sc.close();
    }
}
